  animation: chart-reveal 1800ms cubic-bezier(0.33, 0, 0.15, 1) both;
}

@media (prefers-reduced-motion: reduce) {
  .animate-cell-pop,
  .animate-bar-rise,
  .animate-chart-reveal {
