"use client"

import { Button } from "@/components/boardui/base/buttons/button"
import { Input } from "@/components/boardui/base/input/input"
import { cx } from "@/components/boardui/utils/cx"
import { Check, ChevronRight, Send, SkipForward } from "lucide-react"
import { useState } from "react"

export type InquiryType = "multipleChoice" | "text" | "confirmation" | "scale"
export interface Inquiry {
  id: string
  question: string
  type: InquiryType
  options?: string[]
  required?: boolean
}
export interface InquiryHistoryItem {
  question: string
  answer: string
  timestamp: string
}
export interface AgentInquiryProps {
  agentName?: string
  taskContext?: string
  inquiry?: Inquiry
  inquiryHistory?: InquiryHistoryItem[]
  remainingInquiries?: number
  className?: string
  onSubmit?: (inquiryId: string, answer: string) => void
  onSkip?: (inquiryId: string) => void
}
const defaultInquiry: Inquiry = {
  id: "inq-1",
  question: "Which migration strategy do you prefer?",
  type: "multipleChoice",
  options: ["Blue-green deployment", "Rolling migration", "Canary release"],
  required: true,
}
export function AgentInquiry({
  agentName = "Migration agent",
  taskContext = "Database migration plan",
  inquiry = defaultInquiry,
  inquiryHistory = [],
  remainingInquiries = 0,
  className,
  onSubmit,
  onSkip,
}: AgentInquiryProps) {
  const [selected, setSelected] = useState("")
  const [text, setText] = useState("")
  const answer = inquiry.type === "text" ? text : selected
  const canSubmit = !inquiry.required || Boolean(answer)
  const submit = () => {
    if (canSubmit) onSubmit?.(inquiry.id, answer)
  }
  return (
    <section
      className={cx(
        "border-separator-border bg-background-primary-default overflow-hidden rounded-2xl border",
        className
      )}
    >
      <header className="border-separator-border flex flex-wrap items-center justify-between gap-3 border-b px-4 py-3">
        <div>
          <h3 className="text-headline-semibold">Input required</h3>
          <p className="text-caption-1-regular text-text-secondary">
            {agentName} | {taskContext}
          </p>
        </div>
        <span className="text-caption-1-regular text-text-secondary">
          {remainingInquiries > 0
            ? `${remainingInquiries + 1} decisions remaining`
            : "Final decision"}
        </span>
      </header>
      {inquiryHistory.length > 0 && (
        <details className="border-separator-border border-b">
          <summary className="text-caption-1-medium text-text-secondary flex min-h-10 cursor-pointer items-center gap-2 px-4">
            Previous decisions <span>{inquiryHistory.length}</span>
            <ChevronRight className="ml-auto size-4" />
          </summary>
          <dl className="divide-separator-border bg-background-secondary-default divide-y">
            {inquiryHistory.map((item, index) => (
              <div
                key={`${item.timestamp}-${index}`}
                className="grid gap-1 px-4 py-3 sm:grid-cols-[1fr_1fr_auto]"
              >
                <dt className="text-body-2-regular text-text-secondary">
                  {item.question}
                </dt>
                <dd className="text-body-medium">{item.answer}</dd>
                <dd className="text-caption-1-regular text-text-tertiary">
                  {item.timestamp}
                </dd>
              </div>
            ))}
          </dl>
        </details>
      )}
      <div className="space-y-4 p-4">
        <div>
          <p className="text-body-medium leading-6">{inquiry.question}</p>
          {inquiry.required && (
            <p className="text-caption-1-regular text-text-secondary mt-1">
              A response is required to continue.
            </p>
          )}
        </div>
        {inquiry.type === "multipleChoice" && (
          <div className="divide-separator-border border-separator-border divide-y overflow-hidden rounded-lg border">
            {inquiry.options?.map((option) => (
              <button
                key={option}
                type="button"
                onClick={() => setSelected(option)}
                className={cx(
                  "hover:bg-background-secondary-hover flex min-h-11 w-full items-center gap-3 px-3 text-left",
                  selected === option && "bg-background-secondary-default"
                )}
              >
                <span
                  className={cx(
                    "border-border-button-default grid size-4 place-items-center rounded-full border",
                    selected === option &&
                      "border-button-primary bg-button-primary text-text-white"
                  )}
                >
                  {selected === option && <Check className="size-3" />}
                </span>
                <span className="text-body-2-regular">{option}</span>
              </button>
            ))}
          </div>
        )}
        {inquiry.type === "confirmation" && (
          <div className="flex gap-2">
            <Button
              size="small"
              variant={selected === "Yes" ? "primary" : "secondary"}
              onClick={() => setSelected("Yes")}
            >
              Yes, proceed
            </Button>
            <Button
              size="small"
              variant={selected === "No" ? "primary" : "secondary"}
              onClick={() => setSelected("No")}
            >
              No, skip
            </Button>
          </div>
        )}
        {inquiry.type === "scale" && (
          <div className="flex gap-2" role="radiogroup" aria-label="Rating">
            {[1, 2, 3, 4, 5].map((rating) => (
              <Button
                key={rating}
                size="small"
                variant={selected === String(rating) ? "primary" : "secondary"}
                onClick={() => setSelected(String(rating))}
              >
                {rating}
              </Button>
            ))}
          </div>
        )}
        {inquiry.type === "text" && (
          <Input
            value={text}
            onChange={setText}
            onKeyDown={(event) => {
              if (event.key === "Enter") submit()
            }}
            placeholder="Enter your response"
          />
        )}
      </div>
      <footer className="border-separator-border flex gap-2 border-t px-4 py-3">
        <Button
          size="small"
          leadingIcon={Send}
          disabled={!canSubmit}
          onClick={submit}
        >
          Submit answer
        </Button>
        {!inquiry.required && (
          <Button
            size="small"
            variant="ghost"
            leadingIcon={SkipForward}
            onClick={() => onSkip?.(inquiry.id)}
          >
            Skip
          </Button>
        )}
      </footer>
    </section>
  )
}
AgentInquiry.displayName = "AgentInquiry"

import { cx, sortCx } from "@/components/boardui/utils/cx"
import type {
  AnchorHTMLAttributes,
  ButtonHTMLAttributes,
  ComponentType,
  ReactNode,
  Ref,
} from "react"
import { Focusable } from "react-aria-components"

/**
 * Figma source: Board UI → Buttons (node 3656:13819).
 *
 * Variant matrix from Figma:
 *   Type     = Primary | Secondary | Ghost | Danger
 *   Size     = Medium  | Small | Xs
 *   State    = Default | Hover | Active | Disabled        (CSS pseudo)
 *   OnlyIcon = false   | true
 *
 * Sizing (1:1 with Figma):
 *
 *                       Medium                    Small                     Xs
 *   container          h=36, p=8,   r=10         h=32, px=8 py=6, r=8      h=24, px=8, r=4
 *   gap                 2px                       2px                      1.33px→1
 *   icon                20×20                     18×18                    14×14
 *   label wrapper       px=4                      px=2                     px=2
 *   text style          Body 1/Medium             Body 1/Medium            Caption 1/Semibold
 *   icon-only square    36×36 (content-derived)   32×32 (forced size)      24×24 (forced size)
 *
 * `xs` is the smallest tier - first needed for the calendar template's
 * event-details modal ("Join" / edit-icon buttons, node 3920:10954), which
 * scales every dimension down by the same ~0.667 factor from Figma; the
 * table above rounds those to clean pixel values rather than reproducing
 * the fractional source numbers.
 *
 * Icons are rendered by the component itself via the `leadingIcon` /
 * `trailingIcon` props so the consumer can't pass the wrong size. Pass
 * a Remix Icon component reference (`RiAddLine`, not `<RiAddLine />`).
 *
 * For icon-only buttons:
 *   <Button iconOnly leadingIcon={RiAddLine} aria-label="Add" />
 *
 * The HTML `type` prop is preserved; Figma's "Type" enum is renamed to
 * `variant` to avoid the clash.
 */

type ButtonVariant = "primary" | "secondary" | "ghost" | "danger"
type ButtonSize = "medium" | "small" | "xs"

type IconComponent = ComponentType<{
  className?: string
  "aria-hidden"?: boolean | "true" | "false"
}>

export interface ButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLButtonElement>
}

export interface ButtonLinkProps
  extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLAnchorElement>
}

const styles = sortCx({
  base: [
    "inline-flex items-center justify-center gap-0.5 whitespace-nowrap overflow-hidden",
    "font-sans select-none cursor-pointer",
    "button-press-motion",
    "outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-border-focus-ring",
    "disabled:cursor-not-allowed aria-disabled:cursor-not-allowed",
  ].join(" "),

  // Base shape per size (used when label is present OR medium icon-only).
  size: {
    medium: "h-9 rounded-2lg p-2 text-body-medium",
    small: "h-8 rounded-lg px-2 py-1.5 text-body-medium",
    xs: "h-6 rounded-sm px-2 text-caption-1-semibold",
  },

  // Icon-only override:
  //   Medium → keep p-2; w expands from content (8+20+8 = 36) → square.
  //   Small  → Figma forces 32×32 even though 8+18+8=34, so we hard-set size-8
  //            and zero the padding; the inner flex centers the 18px icon.
  //   Xs     → forces 24×24, content-centered - used for the calendar
  //            template's edit-icon buttons (timezone/participants/reminder).
  iconOnlySize: {
    medium: "", // base size already produces 36×36 with a 20px icon
    small: "size-8 p-0", // hard 32×32, content-centered
    xs: "size-6 p-0", // hard 24×24, content-centered
  },

  icon: {
    medium: "size-5 shrink-0", // 20px
    small: "size-[18px] shrink-0", // 18px
    xs: "size-3.5 shrink-0", // 14px
  },

  label: {
    medium: "inline-flex items-center justify-center px-1 shrink-0", // px=4
    small: "inline-flex items-center justify-center px-0.5 shrink-0", // px=2
    xs: "inline-flex items-center justify-center px-0.5 shrink-0", // px=2
  },

  variant: {
    primary: [
      "bg-button-primary",
      "disabled:text-button-primary-disabled-foreground disabled:shadow-none",
      "aria-disabled:text-button-primary-disabled-foreground aria-disabled:shadow-none",
    ].join(" "),
    danger: [
      "bg-button-danger text-text-white shadow-xs",
      "disabled:text-foreground-disabled-danger disabled:shadow-none",
      "aria-disabled:text-foreground-disabled-danger aria-disabled:shadow-none",
    ].join(" "),
    secondary: [
      "bg-background-primary-default text-text-primary",
      "border border-border-button-default shadow-xs",
      "hover:bg-background-primary-hover  hover:border-border-button-hover",
      "active:bg-background-primary-active active:border-border-button-active",
      "disabled:bg-background-primary-disabled disabled:border-border-button-default disabled:text-text-tertiary disabled:shadow-none",
      "aria-disabled:bg-background-primary-disabled aria-disabled:border-border-button-default aria-disabled:text-text-tertiary aria-disabled:shadow-none",
    ].join(" "),
    ghost: [
      "bg-button-ghost-background text-button-ghost-foreground",
      "hover:bg-button-ghost-hover active:bg-button-ghost-active",
      "disabled:bg-button-ghost-disabled disabled:text-button-ghost-disabled-foreground disabled:shadow-none",
      "aria-disabled:bg-button-ghost-disabled aria-disabled:text-button-ghost-disabled-foreground aria-disabled:shadow-none",
    ].join(" "),
  },
})

export function Button({
  variant = "primary",
  size = "medium",
  iconOnly = false,
  leadingIcon: Leading,
  trailingIcon: Trailing,
  children,
  className,
  type = "button",
  ref,
  ...props
}: ButtonProps) {
  return (
    <Focusable isDisabled={props.disabled}>
      <button
        ref={ref}
        type={type}
        className={cx(
          styles.base,
          styles.size[size],
          styles.variant[variant],
          iconOnly && styles.iconOnlySize[size],
          className
        )}
        {...props}
      >
        {Leading ? <Leading className={styles.icon[size]} aria-hidden /> : null}
        {iconOnly && !Leading && children != null ? (
          <span
            aria-hidden
            className={cx(
              styles.icon[size],
              "inline-flex items-center justify-center [&>svg]:size-full"
            )}
          >
            {children}
          </span>
        ) : null}
        {!iconOnly && children !== undefined && children !== null && (
          <span className={styles.label[size]}>{children}</span>
        )}
        {!iconOnly && Trailing ? (
          <Trailing className={styles.icon[size]} aria-hidden />
        ) : null}
      </button>
    </Focusable>
  )
}

/** Anchor counterpart to Button for navigational actions. */
export function ButtonLink({
  variant = "primary",
  size = "medium",
  iconOnly = false,
  leadingIcon: Leading,
  trailingIcon: Trailing,
  children,
  className,
  ref,
  ...props
}: ButtonLinkProps) {
  return (
    <Focusable>
      <a
        ref={ref}
        className={cx(
          styles.base,
          styles.size[size],
          styles.variant[variant],
          iconOnly && styles.iconOnlySize[size],
          className
        )}
        {...props}
      >
        {Leading ? <Leading className={styles.icon[size]} aria-hidden /> : null}
        {iconOnly && !Leading && children != null ? (
          <span
            aria-hidden
            className={cx(
              styles.icon[size],
              "inline-flex items-center justify-center [&>svg]:size-full"
            )}
          >
            {children}
          </span>
        ) : null}
        {!iconOnly && children !== undefined && children !== null && (
          <span className={styles.label[size]}>{children}</span>
        )}
        {!iconOnly && Trailing ? (
          <Trailing className={styles.icon[size]} aria-hidden />
        ) : null}
      </a>
    </Focusable>
  )
}

