/* Shimmer sweep on a primary call to action (the Pro prompt card). */
@keyframes bui-badge-shimmer {
  0% {
    transform: translateX(0) skewX(-12deg);
  }
  40%,
  100% {
    transform: translateX(350%) skewX(-12deg);
  }
