"use client"

import { StatusPanel } from "@/components/agents-ui/application/status-panel/status-panel"
import type { AgentStatusPanelProps } from "@/components/agents-ui/application/status-panel/status-panel"
import { createElement } from "react"

export type {
  AgentStatusPanelProps,
  ConnectionStatus,
  ModelCapability,
  ModelInfo,
  SystemResources,
} from "@/components/agents-ui/application/status-panel/status-panel"
export function AgentStatusPanel(props: AgentStatusPanelProps) {
  return createElement(StatusPanel, props)
}

"use client"

import { Button } from "@/components/boardui/base/buttons/button"
import { cn } from "@/lib/utils"
import { Power, RefreshCw, Settings } from "lucide-react"
import * as React from "react"

export type ConnectionStatus =
  | "connected"
  | "connecting"
  | "disconnected"
  | "error"
export type ModelCapability =
  | "chat"
  | "code"
  | "vision"
  | "function-calling"
  | "embedding"
export interface ModelInfo {
  name: string
  provider: string
  contextLength: number
  capabilities: ModelCapability[]
  costPer1kTokens?: { input: number; output: number }
}
export interface SystemResources {
  cpu: number
  memory: number
  latency: number
  uptime: string
}
export interface AgentStatusPanelProps {
  connectionStatus?: ConnectionStatus
  modelInfo?: ModelInfo
  systemResources?: SystemResources
  version?: string
  onReconnect?: () => void
  onRefresh?: () => void
  onSettings?: () => void
  className?: string
  compact?: boolean
}
const statusText: Record<ConnectionStatus, string> = {
  connected: "Connected",
  connecting: "Connecting",
  disconnected: "Disconnected",
  error: "Connection error",
}
const statusTone: Record<ConnectionStatus, string> = {
  connected: "text-green-600",
  connecting: "text-accent-600",
  disconnected: "text-text-secondary",
  error: "text-red-600",
}
const capabilityText: Record<ModelCapability, string> = {
  chat: "Chat",
  code: "Code",
  vision: "Vision",
  "function-calling": "Tools",
  embedding: "Embeddings",
}
export function StatusPanel({
  connectionStatus = "connected",
  modelInfo,
  systemResources,
  version = "1.0.0",
  onReconnect,
  onRefresh,
  onSettings,
  className,
  compact = false,
}: AgentStatusPanelProps) {
  const [refreshing, setRefreshing] = React.useState(false)
  const refresh = () => {
    setRefreshing(true)
    onRefresh?.()
    window.setTimeout(() => setRefreshing(false), 1000)
  }
  if (compact)
    return (
      <section
        className={cn(
          "border-separator-border bg-background-primary-default rounded-xl border p-3",
          className
        )}
      >
        <div className="flex items-center justify-between gap-3">
          <span
            className={cn("text-sm font-medium", statusTone[connectionStatus])}
          >
            {statusText[connectionStatus]}
          </span>
          <div className="flex gap-1">
            {connectionStatus === "disconnected" && onReconnect && (
              <Button
                size="xs"
                variant="ghost"
                iconOnly
                leadingIcon={Power}
                aria-label="Reconnect"
                onClick={onReconnect}
              />
            )}
            <Button
              size="xs"
              variant="ghost"
              iconOnly
              leadingIcon={RefreshCw}
              aria-label="Refresh status"
              onClick={refresh}
            />
            {onSettings && (
              <Button
                size="xs"
                variant="ghost"
                iconOnly
                leadingIcon={Settings}
                aria-label="Open settings"
                onClick={onSettings}
              />
            )}
          </div>
        </div>
        {modelInfo && (
          <p className="text-text-secondary mt-2 text-xs">
            {modelInfo.name} · {modelInfo.provider}
          </p>
        )}
      </section>
    )
  return (
    <section
      className={cn(
        "border-separator-border bg-background-primary-default overflow-hidden rounded-xl border",
        className
      )}
    >
      <header className="border-separator-border flex items-start justify-between gap-3 border-b p-4">
        <div>
          <p className="text-text-secondary text-xs font-medium">
            Runtime status
          </p>
          <h2 className="text-text-primary mt-1 text-lg font-semibold">
            Agent connection
          </h2>
          <p className="text-text-secondary mt-1 text-xs">Version {version}</p>
        </div>
        <div className="flex gap-1">
          <Button
            size="small"
            variant="ghost"
            iconOnly
            leadingIcon={RefreshCw}
            aria-label={refreshing ? "Refreshing status" : "Refresh status"}
            onClick={refresh}
          />
          {onSettings && (
            <Button
              size="small"
              variant="ghost"
              iconOnly
              leadingIcon={Settings}
              aria-label="Open settings"
              onClick={onSettings}
            />
          )}
        </div>
      </header>
      <div className="border-separator-border flex items-center justify-between border-b px-4 py-3">
        <span
          className={cn("text-sm font-medium", statusTone[connectionStatus])}
        >
          {statusText[connectionStatus]}
        </span>
        {(connectionStatus === "disconnected" ||
          connectionStatus === "error") &&
          onReconnect && (
            <Button
              size="xs"
              variant="secondary"
              leadingIcon={Power}
              onClick={onReconnect}
            >
              Reconnect
            </Button>
          )}
      </div>
      {modelInfo && (
        <div className="border-separator-border border-b p-4">
          <h3 className="text-text-primary text-sm font-medium">
            {modelInfo.name}
          </h3>
          <p className="text-text-secondary mt-1 text-xs">
            {modelInfo.provider} · {modelInfo.contextLength.toLocaleString()}{" "}
            token context
          </p>
          <div className="mt-3 flex flex-wrap gap-2">
            {modelInfo.capabilities.map((item) => (
              <span
                key={item}
                className="bg-background-secondary-default text-text-secondary rounded-md px-2 py-1 text-xs"
              >
                {capabilityText[item]}
              </span>
            ))}
          </div>
          {modelInfo.costPer1kTokens && (
            <p className="text-text-secondary mt-3 text-xs">
              Input ${modelInfo.costPer1kTokens.input}/1K · Output $
              {modelInfo.costPer1kTokens.output}/1K
            </p>
          )}
        </div>
      )}
      {systemResources && (
        <div className="p-4">
          <p className="text-text-primary text-sm font-medium">Resources</p>
          <div className="mt-3 space-y-3">
            {[
              ["CPU", systemResources.cpu, "%"],
              ["Memory", systemResources.memory, "%"],
              ["Latency", systemResources.latency, " ms"],
            ].map(([label, value, unit]) => (
              <div
                key={label as string}
                className="grid grid-cols-[5rem_1fr_auto] items-center gap-3 text-xs"
              >
                <span className="text-text-secondary">{label}</span>
                <div className="bg-background-secondary-default h-1.5 overflow-hidden rounded-full">
                  <span
                    className="bg-accent-500 block h-full"
                    style={{ width: `${Math.min(Number(value), 100)}%` }}
                  />
                </div>
                <span className="text-text-primary tabular-nums">
                  {value}
                  {unit}
                </span>
              </div>
            ))}
          </div>
          <p className="border-separator-border text-text-secondary mt-3 border-t pt-3 text-xs">
            Uptime {systemResources.uptime}
          </p>
        </div>
      )}
    </section>
  )
}

import { cx, sortCx } from "@/components/boardui/utils/cx"
import type {
  AnchorHTMLAttributes,
  ButtonHTMLAttributes,
  ComponentType,
  ReactNode,
  Ref,
} from "react"
import { Focusable } from "react-aria-components"

/**
 * Figma source: Board UI → Buttons (node 3656:13819).
 *
 * Variant matrix from Figma:
 *   Type     = Primary | Secondary | Ghost | Danger
 *   Size     = Medium  | Small | Xs
 *   State    = Default | Hover | Active | Disabled        (CSS pseudo)
 *   OnlyIcon = false   | true
 *
 * Sizing (1:1 with Figma):
 *
 *                       Medium                    Small                     Xs
 *   container          h=36, p=8,   r=10         h=32, px=8 py=6, r=8      h=24, px=8, r=4
 *   gap                 2px                       2px                      1.33px→1
 *   icon                20×20                     18×18                    14×14
 *   label wrapper       px=4                      px=2                     px=2
 *   text style          Body 1/Medium             Body 1/Medium            Caption 1/Semibold
 *   icon-only square    36×36 (content-derived)   32×32 (forced size)      24×24 (forced size)
 *
 * `xs` is the smallest tier - first needed for the calendar template's
 * event-details modal ("Join" / edit-icon buttons, node 3920:10954), which
 * scales every dimension down by the same ~0.667 factor from Figma; the
 * table above rounds those to clean pixel values rather than reproducing
 * the fractional source numbers.
 *
 * Icons are rendered by the component itself via the `leadingIcon` /
 * `trailingIcon` props so the consumer can't pass the wrong size. Pass
 * a Remix Icon component reference (`RiAddLine`, not `<RiAddLine />`).
 *
 * For icon-only buttons:
 *   <Button iconOnly leadingIcon={RiAddLine} aria-label="Add" />
 *
 * The HTML `type` prop is preserved; Figma's "Type" enum is renamed to
 * `variant` to avoid the clash.
 */

type ButtonVariant = "primary" | "secondary" | "ghost" | "danger"
type ButtonSize = "medium" | "small" | "xs"

type IconComponent = ComponentType<{
  className?: string
  "aria-hidden"?: boolean | "true" | "false"
}>

export interface ButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLButtonElement>
}

export interface ButtonLinkProps
  extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLAnchorElement>
}

const styles = sortCx({
  base: [
