function TaskControl({
  task,
  disabled,
  props,
}: {
  task: AgentTask
  disabled: boolean
  props: AgentTaskQueueProps
}) {
  if (task.status === "running")
    return (
      <Button
        size="xs"
        variant="secondary"
        leadingIcon={Pause}
        disabled={disabled}
        onClick={() => props.onPauseTask?.(task.id)}
      >
        Pause
      </Button>
    )
  if (task.status === "paused")
    return (
      <Button
        size="xs"
        variant="secondary"
        leadingIcon={Play}
        disabled={disabled}
        onClick={() => props.onResumeTask?.(task.id)}
      >
        Resume
      </Button>
    )
  if (task.status === "queued")
    return (
      <Button
        size="xs"
        variant="secondary"
        leadingIcon={Play}
        disabled={disabled}
        onClick={() => props.onStartTask?.(task.id)}
      >
        Start
      </Button>
    )
  if (task.status === "failed")
    return (
      <Button
        size="xs"
        variant="secondary"
        leadingIcon={RefreshCw}
        disabled={disabled}
        onClick={() => props.onCancelTask?.(task.id)}
      >
        Reset
      </Button>
    )
  return null
}

export function TaskQueue(props: AgentTaskQueueProps) {
  const {
    tasks,
    activeTaskId = null,
    autoStart = true,
    concurrencyLimit = 1,
    isProcessing = false,
    showTimeline = true,
    timestamp = "Updated moments ago",
    className,
  } = props
  const records = tasks?.length ? tasks : sampleTasks
  const ordered = activeTaskId
    ? [...records].sort((a, b) =>
        a.id === activeTaskId ? -1 : b.id === activeTaskId ? 1 : 0
      )
    : records
  const queued = records.filter((task) => task.status === "queued")
  const completed = records.filter((task) => task.status === "completed").length
  return (
    <section
      className={cn(
        "border-separator-border bg-background-primary-default overflow-hidden rounded-xl border",
        className
      )}
      aria-label="Agent task queue"
    >
      <header className="border-separator-border flex flex-col gap-3 border-b p-4 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <p className="text-text-secondary text-xs font-medium">
            Execution queue
          </p>
          <h2 className="text-text-primary mt-1 text-lg font-semibold">
            Active work
          </h2>
          <p className="text-text-secondary mt-1 text-sm">
            Monitor current work and control the tasks waiting to run.
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button
            size="small"
            variant="secondary"
            leadingIcon={SlidersHorizontal}
            onClick={() => props.onReorder?.(queued.map((task) => task.id))}
          >
            Optimize
          </Button>
          <Button size="small" leadingIcon={Plus} onClick={props.onAddTask}>
            Add task
          </Button>
        </div>
      </header>
      <div className="border-separator-border text-text-secondary flex flex-wrap items-center gap-x-4 gap-y-2 border-b px-4 py-2.5 text-xs">
        <span>
          {records.filter((task) => task.status === "running").length} running
        </span>
        <span>{queued.length} queued</span>
        <span>{completed} complete</span>
        <span>Limit {concurrencyLimit}</span>
        <Switch
          size="sm"
          isSelected={autoStart}
          onChange={props.onToggleAutoStart}
          className="ml-auto"
        >
          Auto-start
        </Switch>
      </div>
      <div>
        {ordered.map((task) => (
          <article
            key={task.id}
            className="border-separator-border border-b last:border-0"
          >
            <div className="flex items-start gap-3 px-4 py-3">
              <div className="min-w-0 flex-1">
                <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
                  <h3 className="text-text-primary text-sm font-medium">
                    {task.title}
                  </h3>
                  <span className={cn("text-xs", taskStatusClass[task.status])}>
                    {taskStatusText[task.status]}
                  </span>
                </div>
                {task.description && (
                  <p className="text-text-secondary mt-1 text-xs leading-5">
                    {task.description}
                  </p>
                )}
                <div className="text-text-secondary mt-2 flex flex-wrap gap-x-3 text-xs">
                  {task.tool && <span>{task.tool}</span>}
                  {task.updatedLabel && <span>{task.updatedLabel}</span>}
                  {task.estimatedDuration && (
                    <span>{task.estimatedDuration}</span>
                  )}
                </div>
                {typeof task.progress === "number" && (
                  <div className="mt-3 flex items-center gap-3">
                    <div
                      className="bg-background-secondary-default h-1.5 flex-1 overflow-hidden rounded-full"
                      role="progressbar"
                      aria-label={`${task.title} progress`}
                      aria-valuemin={0}
                      aria-valuemax={100}
                      aria-valuenow={task.progress}
                    >
                      <span
                        className="bg-accent-500 block h-full"
                        style={{
                          width: `${Math.max(0, Math.min(100, task.progress))}%`,
                        }}
                      />
                    </div>
                    <span className="text-text-secondary text-xs tabular-nums">
                      {task.progress}%
                    </span>
                  </div>
                )}
              </div>
              <TaskControl task={task} disabled={isProcessing} props={props} />
            </div>
            {(task.checkpoints?.length ||
              task.metrics ||
              task.relatedResources?.length) && (
              <details className="group px-4 pb-3">
                <summary className="text-text-secondary flex w-fit cursor-pointer list-none items-center gap-1 text-xs">
                  <ChevronDown className="size-3.5 transition-transform group-open:rotate-180" />
                  Details
                </summary>
                <div className="bg-background-secondary-default mt-3 grid gap-4 rounded-lg p-3 text-xs sm:grid-cols-2">
                  {showTimeline && task.checkpoints && (
                    <ol className="space-y-2">
                      {task.checkpoints.map((item) => (
                        <li
                          key={item.id}
                          className="flex justify-between gap-3"
                        >
                          <span className="text-text-primary">
                            {item.title}
                          </span>
                          <span className="text-text-secondary">
                            {item.timestamp || item.status}
                          </span>
                        </li>
                      ))}
                    </ol>
                  )}
                  <div className="text-text-secondary space-y-2">
                    {task.metrics?.tokens !== undefined && (
                      <p>{task.metrics.tokens.toLocaleString()} tokens</p>
                    )}
                    {task.metrics?.cost && (
                      <p>{task.metrics.cost} estimated cost</p>
                    )}
                    {task.metrics?.confidence !== undefined && (
                      <p>
                        {Math.round(task.metrics.confidence * 100)}% confidence
                      </p>
                    )}
                    {task.relatedResources?.map((resource) =>
                      resource.href ? (
                        <a
                          className="text-accent-600 block"
                          key={resource.label}
                          href={resource.href}
                        >
                          {resource.label}
                        </a>
                      ) : (
                        <p key={resource.label}>{resource.label}</p>
                      )
                    )}
                  </div>
                </div>
              </details>
            )}
          </article>
        ))}
      </div>
      <footer className="border-separator-border text-text-secondary flex flex-wrap items-center gap-3 border-t px-4 py-3 text-xs">
        <span>{timestamp}</span>
        <span>{records.length} tasks</span>
        {completed > 0 && (
          <button
            type="button"
            className="text-text-primary ml-auto"
            onClick={props.onClearCompleted}
          >
            Clear completed
          </button>
        )}
      </footer>
    </section>
  )
}

import { cx, sortCx } from "@/components/boardui/utils/cx"
import type {
  AnchorHTMLAttributes,
  ButtonHTMLAttributes,
  ComponentType,
  ReactNode,
  Ref,
} from "react"
import { Focusable } from "react-aria-components"

/**
 * Figma source: Board UI → Buttons (node 3656:13819).
 *
 * Variant matrix from Figma:
 *   Type     = Primary | Secondary | Ghost | Danger
 *   Size     = Medium  | Small | Xs
 *   State    = Default | Hover | Active | Disabled        (CSS pseudo)
 *   OnlyIcon = false   | true
 *
 * Sizing (1:1 with Figma):
 *
 *                       Medium                    Small                     Xs
 *   container          h=36, p=8,   r=10         h=32, px=8 py=6, r=8      h=24, px=8, r=4
 *   gap                 2px                       2px                      1.33px→1
 *   icon                20×20                     18×18                    14×14
 *   label wrapper       px=4                      px=2                     px=2
 *   text style          Body 1/Medium             Body 1/Medium            Caption 1/Semibold
 *   icon-only square    36×36 (content-derived)   32×32 (forced size)      24×24 (forced size)
 *
 * `xs` is the smallest tier - first needed for the calendar template's
 * event-details modal ("Join" / edit-icon buttons, node 3920:10954), which
 * scales every dimension down by the same ~0.667 factor from Figma; the
 * table above rounds those to clean pixel values rather than reproducing
 * the fractional source numbers.
 *
 * Icons are rendered by the component itself via the `leadingIcon` /
 * `trailingIcon` props so the consumer can't pass the wrong size. Pass
 * a Remix Icon component reference (`RiAddLine`, not `<RiAddLine />`).
 *
 * For icon-only buttons:
 *   <Button iconOnly leadingIcon={RiAddLine} aria-label="Add" />
 *
 * The HTML `type` prop is preserved; Figma's "Type" enum is renamed to
 * `variant` to avoid the clash.
 */

type ButtonVariant = "primary" | "secondary" | "ghost" | "danger"
type ButtonSize = "medium" | "small" | "xs"

type IconComponent = ComponentType<{
  className?: string
  "aria-hidden"?: boolean | "true" | "false"
}>

export interface ButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLButtonElement>
}

export interface ButtonLinkProps
  extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLAnchorElement>
}

const styles = sortCx({
  base: [
    "inline-flex items-center justify-center gap-0.5 whitespace-nowrap overflow-hidden",
    "font-sans select-none cursor-pointer",
    "button-press-motion",
    "outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-border-focus-ring",
    "disabled:cursor-not-allowed aria-disabled:cursor-not-allowed",
  ].join(" "),

  // Base shape per size (used when label is present OR medium icon-only).
  size: {
    medium: "h-9 rounded-2lg p-2 text-body-medium",
    small: "h-8 rounded-lg px-2 py-1.5 text-body-medium",
    xs: "h-6 rounded-sm px-2 text-caption-1-semibold",
  },

  // Icon-only override:
  //   Medium → keep p-2; w expands from content (8+20+8 = 36) → square.
  //   Small  → Figma forces 32×32 even though 8+18+8=34, so we hard-set size-8
  //            and zero the padding; the inner flex centers the 18px icon.
  //   Xs     → forces 24×24, content-centered - used for the calendar
  //            template's edit-icon buttons (timezone/participants/reminder).
  iconOnlySize: {
