export function Button({
  variant = "primary",
  size = "medium",
  iconOnly = false,
  leadingIcon: Leading,
  trailingIcon: Trailing,
  children,
  className,
  type = "button",
  ref,
  ...props
}: ButtonProps) {
  return (
    <Focusable isDisabled={props.disabled}>
      <button
        ref={ref}
        type={type}
        className={cx(
          styles.base,
          styles.size[size],
          styles.variant[variant],
          iconOnly && styles.iconOnlySize[size],
          className
        )}
        {...props}
