"use client"

import { Button } from "@/components/boardui/base/buttons/button"
import { cx } from "@/components/boardui/utils/cx"
import { ArrowUp, AtSign, Command, Mic, Paperclip, Square } from "lucide-react"
import * as React from "react"

export type PromptBarVariant = "rounded" | "pill"
export interface PromptSource {
  id: string
  label: string
  description?: string
}
export interface PromptCommand {
  id: string
  label: string
  description?: string
}
export interface PromptModel {
  id: string
  label: string
  description?: string
}
export interface PromptBarProps {
  value: string
  onValueChange: (value: string) => void
  onSubmit: (value: string) => void
  onAttach?: () => void
  variant?: PromptBarVariant
  placeholder?: string
  disabled?: boolean
  sources?: PromptSource[]
  commands?: PromptCommand[]
  models?: PromptModel[]
  selectedModel?: string
  onModelChange?: (id: string) => void
  onSourceSelect?: (source: PromptSource) => void
  onCommandSelect?: (command: PromptCommand) => void
  isListening?: boolean
  onDictationToggle?: () => void
  isRunning?: boolean
  onStop?: () => void
  className?: string
}
function token(value: string) {
  const match = /(^|\s)([@/])([\w-]*)$/.exec(value)
  return match
    ? {
        kind: match[2] === "@" ? ("source" as const) : ("command" as const),
        query: match[3].toLowerCase(),
        start: match.index + match[1].length,
      }
    : null
}
export function PromptBar({
  value,
  onValueChange,
  onSubmit,
  onAttach,
  variant = "rounded",
  placeholder = "Ask anything",
  disabled = false,
  sources = [],
  commands = [],
  models = [],
  selectedModel,
  onModelChange,
  onSourceSelect,
  onCommandSelect,
  isListening = false,
  onDictationToggle,
  isRunning = false,
  onStop,
  className,
}: PromptBarProps) {
  const current = token(value)
  const [menu, setMenu] = React.useState<"source" | "command" | null>(null)
  const [active, setActive] = React.useState(0)
  const [dismissedValue, setDismissedValue] = React.useState<string>()
  const kind = menu ?? (dismissedValue === value ? null : current?.kind) ?? null
  const query = menu ? "" : (current?.query ?? "")
  const options =
    kind === "source"
      ? sources.filter((item) =>
          `${item.label} ${item.description ?? ""}`
            .toLowerCase()
            .includes(query)
        )
      : kind === "command"
        ? commands.filter((item) =>
            `${item.label} ${item.description ?? ""}`
              .toLowerCase()
              .includes(query)
          )
        : []
  const close = () => {
    setDismissedValue(value)
    setMenu(null)
    setActive(0)
  }
  const select = (index: number) => {
    const option = options[index]
    if (!option || !kind) return
    const inserted = kind === "source" ? `@${option.label}` : `/${option.label}`
    onValueChange(
      current
        ? `${value.slice(0, current.start)}${inserted} `
        : `${value}${value ? " " : ""}${inserted} `
    )
    if (kind === "source") onSourceSelect?.(option as PromptSource)
    else onCommandSelect?.(option as PromptCommand)
    close()
  }
  const submit = () => {
    const text = value.trim()
    if (text && !disabled && !isRunning) onSubmit(text)
  }
  return (
    <div className={cx("relative", className)}>
      {kind && options.length > 0 && !disabled && !isRunning && (
        <div
          role="listbox"
          aria-label={kind === "source" ? "Data sources" : "Commands"}
          className="border-separator-border bg-background-primary-default absolute bottom-full z-20 mb-2 w-full max-w-sm rounded-xl border p-1.5 shadow-lg"
        >
          {options.map((option, index) => (
            <button
              key={option.id}
              type="button"
              role="option"
              aria-selected={active === index}
              onMouseEnter={() => setActive(index)}
              onClick={() => select(index)}
              className={cx(
                "flex min-h-9 w-full items-center gap-2 rounded-lg px-2 text-left",
                active === index && "bg-background-secondary-default"
              )}
            >
              <span className="text-xs font-medium">
                {kind === "source" ? "@" : "/"}
                {option.label}
              </span>
              {option.description && (
                <span className="text-text-secondary ml-auto text-xs">
                  {option.description}
                </span>
              )}
            </button>
          ))}
        </div>
      )}
      <div
        className={cx(
          "border-separator-border bg-background-primary-default flex min-h-11 items-center gap-1.5 border p-1.5",
          variant === "pill" ? "rounded-full" : "rounded-xl"
        )}
      >
        <Button
          variant="ghost"
          size="small"
          iconOnly
          aria-label="Attach file"
          leadingIcon={Paperclip}
          disabled={disabled || isRunning}
          onClick={onAttach}
        />
        {sources.length > 0 && (
          <Button
            variant="ghost"
            size="small"
            iconOnly
            aria-label="Mention a data source"
            leadingIcon={AtSign}
            disabled={disabled || isRunning}
            onClick={() => {
              setMenu(menu === "source" ? null : "source")
              setActive(0)
            }}
          />
        )}{" "}
        {commands.length > 0 && (
          <Button
            variant="ghost"
            size="small"
            iconOnly
            aria-label="Choose a command"
            leadingIcon={Command}
            disabled={disabled || isRunning}
            onClick={() => {
              setMenu(menu === "command" ? null : "command")
              setActive(0)
            }}
          />
        )}
        <input
          value={value}
          disabled={disabled || isRunning}
          onChange={(event) => {
            onValueChange(event.target.value)
            setMenu(null)
            setActive(0)
          }}
          onKeyDown={(event) => {
            if (
              kind &&
              options.length &&
              (event.key === "ArrowDown" || event.key === "ArrowUp")
            ) {
              event.preventDefault()
              setActive((index) =>
                event.key === "ArrowDown"
                  ? Math.min(options.length - 1, index + 1)
                  : Math.max(0, index - 1)
              )
              return
            }
            if (
              kind &&
              options.length > 0 &&
              event.key === "Enter" &&
              !event.nativeEvent.isComposing
            ) {
              event.preventDefault()
              select(active)
              return
            }
            if (event.key === "Escape" && kind) {
              event.preventDefault()
              close()
              return
            }
            if (
              event.key === "Enter" &&
              !event.nativeEvent.isComposing &&
              !disabled &&
              !isRunning
            ) {
              event.preventDefault()
              submit()
            }
          }}
          placeholder={placeholder}
          className="placeholder:text-text-tertiary min-w-0 flex-1 bg-transparent px-1 text-[13px] outline-none disabled:cursor-not-allowed"
        />
        {models.length > 0 && (
          <select
            aria-label="Model"
            value={selectedModel}
            disabled={disabled || isRunning}
            onChange={(event) => onModelChange?.(event.target.value)}
            className="bg-background-secondary-default h-8 max-w-28 rounded-lg px-2 text-xs outline-none"
          >
            <option value="" disabled>
              Model
            </option>
            {models.map((model) => (
              <option key={model.id} value={model.id}>
                {model.label}
              </option>
            ))}
          </select>
        )}
        {onDictationToggle && (
          <Button
            variant="ghost"
            size="small"
            iconOnly
            aria-label={isListening ? "Stop dictation" : "Start dictation"}
            aria-pressed={isListening}
            leadingIcon={Mic}
            disabled={disabled || isRunning}
            onClick={onDictationToggle}
          />
        )}{" "}
        {isRunning ? (
          <Button
            variant="secondary"
            size="small"
            iconOnly
            aria-label="Stop generation"
            leadingIcon={Square}
            disabled={disabled}
            onClick={onStop}
          />
        ) : (
          <Button
            size="small"
            iconOnly
            aria-label="Send prompt"
            leadingIcon={ArrowUp}
            disabled={disabled || !value.trim()}
            onClick={submit}
          />
        )}
      </div>
    </div>
  )
}

import { cx, sortCx } from "@/components/boardui/utils/cx"
import type {
  AnchorHTMLAttributes,
  ButtonHTMLAttributes,
  ComponentType,
  ReactNode,
  Ref,
} from "react"
import { Focusable } from "react-aria-components"

/**
 * Figma source: Board UI → Buttons (node 3656:13819).
 *
 * Variant matrix from Figma:
 *   Type     = Primary | Secondary | Ghost | Danger
 *   Size     = Medium  | Small | Xs
 *   State    = Default | Hover | Active | Disabled        (CSS pseudo)
 *   OnlyIcon = false   | true
 *
 * Sizing (1:1 with Figma):
 *
 *                       Medium                    Small                     Xs
 *   container          h=36, p=8,   r=10         h=32, px=8 py=6, r=8      h=24, px=8, r=4
 *   gap                 2px                       2px                      1.33px→1
 *   icon                20×20                     18×18                    14×14
 *   label wrapper       px=4                      px=2                     px=2
 *   text style          Body 1/Medium             Body 1/Medium            Caption 1/Semibold
 *   icon-only square    36×36 (content-derived)   32×32 (forced size)      24×24 (forced size)
 *
 * `xs` is the smallest tier - first needed for the calendar template's
 * event-details modal ("Join" / edit-icon buttons, node 3920:10954), which
 * scales every dimension down by the same ~0.667 factor from Figma; the
 * table above rounds those to clean pixel values rather than reproducing
 * the fractional source numbers.
 *
 * Icons are rendered by the component itself via the `leadingIcon` /
 * `trailingIcon` props so the consumer can't pass the wrong size. Pass
 * a Remix Icon component reference (`RiAddLine`, not `<RiAddLine />`).
 *
 * For icon-only buttons:
 *   <Button iconOnly leadingIcon={RiAddLine} aria-label="Add" />
 *
 * The HTML `type` prop is preserved; Figma's "Type" enum is renamed to
 * `variant` to avoid the clash.
 */

type ButtonVariant = "primary" | "secondary" | "ghost" | "danger"
type ButtonSize = "medium" | "small" | "xs"

type IconComponent = ComponentType<{
  className?: string
  "aria-hidden"?: boolean | "true" | "false"
}>

export interface ButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLButtonElement>
}

export interface ButtonLinkProps
  extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLAnchorElement>
}

const styles = sortCx({
  base: [
    "inline-flex items-center justify-center gap-0.5 whitespace-nowrap overflow-hidden",
    "font-sans select-none cursor-pointer",
    "button-press-motion",
    "outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-border-focus-ring",
    "disabled:cursor-not-allowed aria-disabled:cursor-not-allowed",
  ].join(" "),

  // Base shape per size (used when label is present OR medium icon-only).
  size: {
    medium: "h-9 rounded-2lg p-2 text-body-medium",
    small: "h-8 rounded-lg px-2 py-1.5 text-body-medium",
    xs: "h-6 rounded-sm px-2 text-caption-1-semibold",
  },

  // Icon-only override:
  //   Medium → keep p-2; w expands from content (8+20+8 = 36) → square.
  //   Small  → Figma forces 32×32 even though 8+18+8=34, so we hard-set size-8
  //            and zero the padding; the inner flex centers the 18px icon.
  //   Xs     → forces 24×24, content-centered - used for the calendar
  //            template's edit-icon buttons (timezone/participants/reminder).
  iconOnlySize: {
    medium: "", // base size already produces 36×36 with a 20px icon
    small: "size-8 p-0", // hard 32×32, content-centered
    xs: "size-6 p-0", // hard 24×24, content-centered
  },

  icon: {
    medium: "size-5 shrink-0", // 20px
    small: "size-[18px] shrink-0", // 18px
    xs: "size-3.5 shrink-0", // 14px
  },

  label: {
    medium: "inline-flex items-center justify-center px-1 shrink-0", // px=4
    small: "inline-flex items-center justify-center px-0.5 shrink-0", // px=2
    xs: "inline-flex items-center justify-center px-0.5 shrink-0", // px=2
  },

  variant: {
    primary: [
      "bg-button-primary",
      "disabled:text-button-primary-disabled-foreground disabled:shadow-none",
      "aria-disabled:text-button-primary-disabled-foreground aria-disabled:shadow-none",
    ].join(" "),
    danger: [
      "bg-button-danger text-text-white shadow-xs",
      "disabled:text-foreground-disabled-danger disabled:shadow-none",
      "aria-disabled:text-foreground-disabled-danger aria-disabled:shadow-none",
    ].join(" "),
    secondary: [
      "bg-background-primary-default text-text-primary",
      "border border-border-button-default shadow-xs",
      "hover:bg-background-primary-hover  hover:border-border-button-hover",
      "active:bg-background-primary-active active:border-border-button-active",
      "disabled:bg-background-primary-disabled disabled:border-border-button-default disabled:text-text-tertiary disabled:shadow-none",
      "aria-disabled:bg-background-primary-disabled aria-disabled:border-border-button-default aria-disabled:text-text-tertiary aria-disabled:shadow-none",
    ].join(" "),
    ghost: [
