  --shadow-xl: 0 10px 10px -5px rgb(0 0 0 / 0.08), 0 20px 25px -5px rgb(0 0 0 / 0.20);
  --shadow-card: 0 1px 1px 0 rgb(0 0 0 / 0.14);
