"use client"

import { cx } from "@/components/boardui/utils/cx"
import { Search } from "lucide-react"
import * as React from "react"

export interface SearchListItem {
  id: string
  label: string
  description?: string
}
export interface SearchListProps {
  value: string
  items: SearchListItem[]
  onValueChange: (value: string) => void
  onSelect?: (id: string) => void
  placeholder?: string
  className?: string
}
export function SearchList({
  value,
  items,
  onValueChange,
  onSelect,
  placeholder = "Search",
  className,
}: SearchListProps) {
  const [activeIndex, setActiveIndex] = React.useState(0)
  const visible = items.filter((item) =>
    `${item.label} ${item.description ?? ""}`
      .toLowerCase()
      .includes(value.toLowerCase())
  )
  return (
    <section
      className={cx(
        "border-separator-border bg-background-primary-default max-w-xl rounded-xl border p-3",
        className
      )}
    >
      <label className="border-separator-border flex h-10 items-center gap-2 border-b px-2">
        <Search className="text-text-secondary size-4" />
        <input
          value={value}
          onChange={(e) => onValueChange(e.target.value)}
          onKeyDown={(event) => {
            if (event.key === "ArrowDown") {
              event.preventDefault()
              setActiveIndex((index) => Math.min(visible.length - 1, index + 1))
            } else if (event.key === "ArrowUp") {
              event.preventDefault()
              setActiveIndex((index) => Math.max(0, index - 1))
            } else if (event.key === "Enter" && visible[activeIndex]) {
              event.preventDefault()
              onSelect?.(visible[activeIndex].id)
            }
          }}
          placeholder={placeholder}
          className="flex-1 bg-transparent text-[13px] outline-none"
        />
      </label>
      <div className="divide-separator-border mt-2 divide-y">
        {visible.map((item, index) => (
          <button
            key={item.id}
            onClick={() => onSelect?.(item.id)}
            className={cx(
              "min-h-10 w-full px-2 text-left",
              index === activeIndex && "bg-background-secondary-default"
            )}
          >
            <span className="block text-[13px] font-medium">{item.label}</span>
            {item.description && (
              <span className="text-text-secondary block text-xs">
                {item.description}
              </span>
            )}
          </button>
        ))}
        {visible.length === 0 && (
          <p className="text-text-secondary p-6 text-center text-[13px]">
            No results
          </p>
        )}
      </div>
    </section>
  )
}

import { extendTailwindMerge } from "tailwind-merge";

/**
 * Text-style classes from styles/typography.css.
 *
 * IMPORTANT: every text-* utility we define via @theme (e.g. `text-body-medium`,
 * `text-title-1-semibold`) must be listed here. Otherwise tailwind-merge — which
 * has no view of our Tailwind theme — treats them as text-color utilities and
 * silently drops them when they appear in the same className as a real color
 * (`text-foreground-full`, `text-text-primary`, etc).
 *
 * If you add or rename a text style in typography.css, mirror the change here.
 */
const TEXT_FAMILIES = [
  "large-title",
  "display-1",
  "display-2",
  "display-3",
  "display-4",
  "title-1",
  "title-2",
  "title-3",
  "headline",
  "body",
  "body-2",
  "caption-1",
  "caption-2",
] as const;

const TEXT_WEIGHTS = ["regular", "medium", "semibold", "bold"] as const;

const TEXT_STYLE_SUFFIXES = TEXT_FAMILIES.flatMap((family) =>
  TEXT_WEIGHTS.map((weight) => `${family}-${weight}`),
);

const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [{ text: TEXT_STYLE_SUFFIXES }],
    },
  },
});

/**
 * Merge Tailwind classes safely. Last-write-wins on conflicting utilities.
 */
export const cx = twMerge;

/**
 * Identity helper that gives the Tailwind IntelliSense extension a hook for
 * sorting classes inside style objects (the extension doesn't sort inside
 * plain object literals otherwise).
 */
export function sortCx<
  T extends Record<
    string,
    string | number | Record<string, string | number | Record<string, string | number>>
  >,
>(classes: T): T {
  return classes;
}

