  --shadow-card: 0 1px 1px 0 rgb(0 0 0 / 0.14);
  --shadow-dropdown:
    0 1px 1px 0 rgb(0 0 0 / 0.14),
    0 4px 4px 0 rgb(0 0 0 / 0.10);
